mapper.insert:

    SELECT
        'CMTE'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(TEM_NO), LENGTH('CMTE' ) + 1)), 0) + 1, 6, '0')
    FROM COM_MAIL_TEM

INSERT INTO COM_MAIL_TEM (
	TEM_NO
	, USER_ID
	, TEM_TITLE
	, TEM_CONTENT
	, CREATE_DATE
) VALUES (
	#{temNo}
	, #{userId}
	, #{temTitle}
	, #{temContent}
	, SYSDATE
)

mapper.update:
UPDATE COM_MAIL_TEM
SET 
	TEM_TITLE = #{temTitle}
	, TEM_CONTENT = #{temContent}
WHERE TEM_NO = #{temNo}
AND USER_ID = #{userId}

UPDATE COM_MAIL_TEM
SET 
	DELETE_DATE = SYSDATE
WHERE TEM_NO = #{temNo}
AND USER_ID = #{userId}
